// Derives WebP renditions from the archival JPEGs in public/history.
//
// The originals are full-resolution museum downloads (up to 1920x2880, ~1MB).
// Cards render them at roughly 200px tall and the day cover at ~280px, so the
// page was shipping about ten times the pixels it draws. Each image gets a
// small and a large WebP; the JPEG stays as the <img src> fallback and as the
// file a reader can still open directly.
//
// Output goes to public/history/derived/ and is regenerated by `npm run build`.
import fs from "node:fs";
import path from "node:path";
import sharp from "sharp";

const source = path.resolve("public/history");
const target = path.join(source, "derived");
const manifestPath = path.resolve("data/image-sizes.json");
// Small covers every card and thumbnail; large covers the cover art and the
// lightbox on high-density screens.
const WIDTHS = { sm: 640, lg: 1280 };
const QUALITY = 78;

const files = fs
  .readdirSync(source)
  .filter((f) => f.endsWith(".jpg"))
  .sort();
fs.mkdirSync(target, { recursive: true });

const keep = new Set();
const manifest = {};
let generated = 0;
let reused = 0;

for (const file of files) {
  const id = file.slice(0, -4);
  const input = path.join(source, file);
  const meta = await sharp(input).metadata();
  manifest[id] = { width: meta.width, height: meta.height, variants: [] };

  for (const [label, width] of Object.entries(WIDTHS)) {
    // Never upscale: a 637px original has no useful 1280px rendition.
    if (meta.width < width && label !== "sm") continue;
    const outputWidth = Math.min(width, meta.width);
    const name = `${id}-${label}.webp`;
    const output = path.join(target, name);
    keep.add(name);
    manifest[id].variants.push({
      label,
      width: outputWidth,
      src: `/history/derived/${name}`,
    });
    // Skip work when the rendition is already newer than its source.
    if (
      fs.existsSync(output) &&
      fs.statSync(output).mtimeMs >= fs.statSync(input).mtimeMs
    ) {
      reused++;
      continue;
    }
    await sharp(input)
      .resize({ width: outputWidth, withoutEnlargement: true })
      .webp({ quality: QUALITY })
      .toFile(output);
    generated++;
  }
}

for (const file of fs.readdirSync(target))
  if (!keep.has(file)) fs.unlinkSync(path.join(target, file));

fs.writeFileSync(manifestPath, JSON.stringify(manifest, null, 2) + "\n");

const bytes = (dir, filter) =>
  fs
    .readdirSync(dir)
    .filter(filter)
    .reduce((n, f) => n + fs.statSync(path.join(dir, f)).size, 0);
const originals = bytes(source, (f) => f.endsWith(".jpg"));
const small = bytes(target, (f) => f.endsWith("-sm.webp"));
console.log(
  JSON.stringify(
    {
      images: files.length,
      generated,
      reused,
      originalsKb: Math.round(originals / 1024),
      smallSetKb: Math.round(small / 1024),
      errors: [],
    },
    null,
    2,
  ),
);
